insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, effective_note, verification_status) values ((select id from rules where slug = 'fhsaa-nil-allowed'), 1, 'yes_with_conditions', 'Yes. FHSAA athletes may profit from their name, image and likeness as long as they follow Bylaw 9.9.', 'Every other row in this matrix is one of those conditions.', 'FHSAA Bylaw 9.9.4', 'Approved by the FHSAA Board on June 4, 2024. State Board of Education ratification was on the July 24, 2024 agenda; the vote record and exact effective date were not found in a primary document.', 'needs_verification');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-nil-allowed' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9.4', 'A student-athlete may profit from the use of their Name, Image, and Likeness subject to their compliance with FHSAA Bylaw 9.9.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-nil-allowed' and v.is_current), (select id from sources where slug = 'fhsaa-letter-2024-06-21'), 'Letter, first paragraph', 'On June 4, 2024, the Florida High School Athletic Association''s (FHSAA) Board of Directors unanimously approved the revision of FHSAA Bylaw 9.9, Amateurism, to include Name, Image, and Likeness (NIL)', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
