insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status) values ((select id from rules where slug = 'fhsaa-sponsored-posts'), 1, 'yes_with_conditions', 'Yes. Endorsements, promotions, social media presence and product or service advertisements are all named as permitted activities.', 'Subject to the prohibited categories, school marks and Form GA1 rules in this matrix.', 'FHSAA Bylaw 9.9.4', 'needs_verification');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-sponsored-posts' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9.4', 'Permissible activities include, but are not limited to, commercial endorsements, promotional activities, social media presence, product, or service advertisements.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
