insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-deal-terms' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9.4.1', 'An NIL agreement is a fully executed, written contract that allows for student-athletes to profit from or be compensated for promoting, partnering, and/or representing product endorsements and other activities as defined in FHSAA Bylaw 9.9.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
