insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status) values ((select id from rules where slug = 'fhsaa-pay-for-play'), 1, 'no', 'No. Competing for money and cashing in on athletic performance still put amateur status at risk, and so does any NIL agreement that does not follow Bylaw 9.9.', 'FHSAA Bylaw 9.9.2 (a), (c), (f)', 'needs_verification');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-pay-for-play' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9.2', 'a) Competing for money or other monetary compensations; ... c) Capitalizing on athletic fame or performance by receiving money or gifts of a monetary nature; ... f) Accepting a Name, Image, and Likeness (NIL) agreement that does not adhere to FHSAA Bylaw 9.9.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-pay-for-play' and v.is_current), 'needs_verification', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Source opened and quote extracted by automated research. Human check pending.');
insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('fhsaa-school-logos-marks', (select id from rule_topics where slug = 'school-logos-marks'), 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status) values ((select id from rules where slug = 'fhsaa-school-logos-marks'), 1, 'only_with_approval', 'Not without prior written consent. The bylaw bars using a member school''s, FHSAA''s or NFHS''s uniforms, logos, mascots, insignia or identifying marks in NIL activity. It allows a school''s uniform, equipment, logo and name with prior written consent from the school, district or governing body, and Form GA1 records that consent for member school marks.', 'We found no consent path for FHSAA or NFHS marks, or for references to events, games or championships.', 'FHSAA Bylaw 9.9.4.3; Form GA1 Section B', 'needs_verification');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-school-logos-marks' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9.4.3, first sentence', 'Student-athletes are prohibited from making any reference to and will not otherwise use or authorize others to use the uniforms, logos, mascots, insignia, or identifying marks of a member school, the FHSAA, the NFHS, and/or any FHSAA, NFHS, or member school event, game, or championship when engaging in any NIL activity.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-school-logos-marks' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9.4.3, second sentence', 'Student-athletes will be prohibited from monetizing their Name, Image, and Likeness with the use of their school''s uniform, equipment, logo, name, proprietary patents, products, and/or copyrights associated with an FHSAA member school, NFHS, and/or school district, either in public, print, or social media platforms, unless granted authorization by prior written consent from the school, district or governing body of the school, or Association, respectively.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-school-logos-marks' and v.is_current), (select id from sources where slug = 'fhsaa-form-ga1'), 'Section B', 'In accordance with FHSAA Bylaw 9.9.4.3 above, this school, school district, or governing body provided written consent authorizing the above student to use member school uniforms, logos, mascots, insignia, or identifying marks. [ ___ Yes] [ ___ No] *Required', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
