insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('fhsaa-collectives', (select id from rule_topics where slug = 'collectives'), 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status) values ((select id from rules where slug = 'fhsaa-collectives'), 1, 'no', 'No. NIL collectives are a prohibited category. The definition is broad: any group that pools money to arrange, fund or promote NIL. School sanctioned team fundraising does not count as a collective.', 'FHSAA Bylaw 9.9.4.2 and 9.9.4.4(i)', 'needs_verification');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-collectives' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9.4.2', 'NIL Collectives include but are not limited to, groups, organizations, or cooperative enterprises that exist to collect funds from donors, individuals, or businesses to: 1) help facilitate NIL deals for student-athletes; 2) facilitate payments to or transfers funds to student-athletes; 3) create ways for athletes to monetize from their NIL; and/or 4) otherwise promote NIL for schools or student-athletes. NIL Collective shall not include school sanctioned team fundraising.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-collectives' and v.is_current), 'needs_verification', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Source opened and quote extracted by automated research. Human check pending.');
insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('fhsaa-school-staff', (select id from rule_topics where slug = 'school-staff-involvement'), 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status) values ((select id from rules where slug = 'fhsaa-school-staff'), 1, 'no', 'No. School employees, athletic department staff and representatives of the school''s athletic interests may not form, direct, offer, provide or otherwise take part in NIL activity.', 'FHSAA Bylaw 9.9.4.5', 'needs_verification');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-school-staff' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9.4.5', 'No school employee, athletic department staff member, or representative of a school''s athletic interests as defined in Bylaw 1.4.17 (a-e), may form, direct, offer, provide, or otherwise engage in any activity outlined in FHSAA Bylaw 9.9.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-school-staff' and v.is_current), 'needs_verification', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Source opened and quote extracted by automated research. Human check pending.');
insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('fhsaa-boosters', (select id from rule_topics where slug = 'boosters'), 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status) values ((select id from rules where slug = 'fhsaa-boosters'), 1, 'no', 'No. A member of a school''s athletic booster organization counts as a representative of the school''s athletic interests, and those representatives may not engage in NIL activity. The same definition covers volunteers and immediate relatives of coaches.', 'The same definition also lists student-athletes and their family members, so how Bylaw 9.9.4.5 applies to them is unclear and needs FHSAA confirmation.', 'FHSAA Bylaws 9.9.4.5 and 1.4.17 (a)-(e)', 'needs_verification');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-boosters' and v.is_current), (select id from sources where slug = 'fhsaa-handbook-2024-25'), 'Bylaw 1.4.17', 'Representative of a School''s Athletic Interests – refers to any independent person, business, organization, or group that participates in, assists with and/or promotes that school''s interscholastic athletic program. This includes: (a) A student-athlete or other student participant in the athletic program at that school; (b) The parents, guardians or other family members of a student-athlete or other student participant; (c) Immediate relatives of a coach or other member of the athletic department staff; (d) A volunteer with that school''s athletic program; (e) A member of an athletic booster organization of that school', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-boosters' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9.4.5', 'No school employee, athletic department staff member, or representative of a school''s athletic interests as defined in Bylaw 1.4.17 (a-e), may form, direct, offer, provide, or otherwise engage in any activity outlined in FHSAA Bylaw 9.9.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
