insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status) values ((select id from rules where slug = 'fhsaa-agents'), 1, 'yes_with_conditions', 'Only for NIL. Hiring an agent to manage an athletic career can cost amateur status, but an agent hired to advise on NIL matters is allowed.', 'The ratification text reads "registered agent"; whether the final handbook keeps the word "registered" needs a human check.', 'FHSAA Bylaw 9.9.2(d)', 'needs_verification');
