insert into rule_versions (rule_id, version_no, answer, summary, citation, effective_note, verification_status) values ((select id from rules where slug = 'fhsaa-disclosure'), 1, 'yes', 'Yes. Any athlete who does NIL must complete Form GA1 and give it to the school within five business days of signing an NIL agreement. The school completes its section and sends a copy to FHSAA.', 'FHSAA Bylaw 9.9.5; Form GA1', 'Added by the FHSAA Board in September 2024.', 'needs_verification');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-disclosure' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-5-sbe-2024'), 'Bylaw 9.9.5', 'A student who engages in any NIL activity must sign an ''Affidavit of Compliance with the Regulations on Amateurism and Interscholastic Athletic Eligibility.'' ... The student/parent must complete, obtain all applicable signatures and submit this form to the school within five (5) business days of signing a Name, Image, and Likeness (NIL) agreement.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-disclosure' and v.is_current), (select id from sources where slug = 'fhsaa-form-ga1'), 'Sections A and B', 'THIS STUDENT has engaged in a Name, Image, and Likeness (NIL) agreement with: ____ ... Once Section B is completed, please send a scanned copy of this form to NIL@fhsaa.org.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into disclosure_requirements (rule_version_id, what, recipient, deadline_text, deadline_business_days, form_name, form_url) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-disclosure' and v.is_current), 'Form GA1 (Affidavit of Compliance), naming the other party to the NIL agreement and signed by the student and a parent or legal guardian', 'Your school. The school completes Section B and emails a copy to FHSAA.', 'Within five business days of signing an NIL agreement', 5, 'FHSAA Form GA1', 'https://www.fldoe.org/core/fileparse.php/20872/urlt/10-3.pdf');
