insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('fhsaa-parent-guardian', (select id from rule_topics where slug = 'parent-guardian'), 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status) values ((select id from rules where slug = 'fhsaa-parent-guardian'), 1, 'yes_with_conditions', 'A parent or legal guardian signs Form GA1 with the student, under penalties of perjury. By entering an NIL agreement, the student and parents also release the school, district and FHSAA from liability tied to the deal.', 'Bylaw 9.9 does not itself say a parent must co-sign the NIL contract. Whether Florida contract law requires it for a minor was not verified here. The subsection number for the release (9.9.4.1.1) needs a human check.', 'Form GA1 Section A; FHSAA Bylaw 9.9.4.1.1', 'needs_verification');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-parent-guardian' and v.is_current), (select id from sources where slug = 'fhsaa-form-ga1'), 'Section A', 'Signature of Student / Signature of Parent/Legal Guardian ... Under penalties of perjury, I declare that I have read the foregoing Affidavit and that the facts stated therein are true and correct', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-parent-guardian' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9.4.1.1', 'By entering into an NIL agreement, the student-athlete and his/her parent(s)/guardian(s) release their school, its district or governing body, and FHSAA from any liability related to, or arising from the NIL agreement.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-parent-guardian' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9, opening section', 'Student-athletes and their families are encouraged to seek legal counsel and tax advice when considering NIL activity.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
