insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('fhsaa-recruiting', (select id from rule_topics where slug = 'recruiting-inducement'), 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status) values ((select id from rules where slug = 'fhsaa-recruiting'), 1, 'no', 'No. NIL may not be used to pressure, urge or entice an athlete to attend a school to play sports.', 'FHSAA Bylaw 9.9.4.6', 'needs_verification');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-recruiting' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9.4.6', 'NIL activities shall not be used to pressure, urge, or entice a student-athlete to attend a school for the purpose of participating in interscholastic athletics.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
