insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('fhsaa-contract-length', (select id from rule_topics where slug = 'contract-length'), 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status) values ((select id from rules where slug = 'fhsaa-contract-length'), 1, 'yes_with_conditions', 'A deal is limited to the athlete''s high school eligibility and cannot extend past the high school graduation date.', 'The exact subsection number (9.9.4.1 or 9.9.4.1.1) needs a human check.', 'FHSAA Bylaw 9.9.4.1', 'needs_verification');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-contract-length' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Bylaw 9.9.4.1', 'An NIL agreement is limited to a student-athlete''s high school period of athletic eligibility and shall not extend beyond a student-athlete''s high school graduation date.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-contract-length' and v.is_current), 'needs_verification', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Source opened and quote extracted by automated research. Human check pending.');
insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('fhsaa-penalties', (select id from rule_topics where slug = 'penalties'), 'governing_body', (select id from governing_bodies where slug = 'fhsaa'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status) values ((select id from rules where slug = 'fhsaa-penalties'), 1, 'yes', 'Penalties escalate. First violation: a formal warning, and the deal must be ended or changed and any compensation returned. Second: ineligible to represent any member school for one year. Third: ineligible for the rest of the athlete''s high school career. An athlete who falsifies information or receives an impermissible benefit will be deemed ineligible under Bylaw 9.1.2.2 or Policy 36.5.2.', 'FHSAA Bylaw 9.9.6.3 (numbered 9.9.5.3 before September 2024)', 'needs_verification');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-penalties' and v.is_current), (select id from sources where slug = 'fhsaa-bylaw-9-9-sbe-2024'), 'Penalties section', 'Any violation by a student-athlete of the provisions of Bylaw 9.9 shall result in escalating sanctions. However, a student-athlete who falsifies information or who receives an impermissible benefit will be deemed ineligible in accordance with Bylaw 9.1.2.2 or Policy 36.5.2, respectively. ... the student-athlete shall receive a formal warning. If applicable, the student shall immediately terminate/modify the NIL agreement, remove any advertisement, promotional activity, or endorsement, and return any awards, gifts, or other compensation. ... the student-athlete will be ineligible to represent any member school for a period of one year from the date of discovery. ... the student-athlete will be ineligible to compete in any interscholastic athletic contest in any sport for the duration of the student-athlete''s high school career.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fhsaa-penalties' and v.is_current), 'needs_verification', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Source opened and quote extracted by automated research. Human check pending.');
insert into rules (slug, rule_topic_id, scope_type, state_id, applies_to) values ('fl-hs-no-statute', (select id from rule_topics where slug = 'nil-allowed'), 'state', (select id from states where code = 'FL'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status) values ((select id from rules where slug = 'fl-hs-no-statute'), 1, 'not_addressed', 'We found no Florida statute on high school NIL. Section 1006.20(2)(a) requires FHSAA bylaw changes to be ratified by the State Board of Education, so the FHSAA bylaw is the rule we cite.', 'Section 1006.20(2)(a), Florida Statutes', 'researched');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-hs-no-statute' and v.is_current), (select id from sources where slug = 'fl-stat-1006-20'), 's. 1006.20(2)(a)', 'Any changes to the FHSAA''s bylaws must be ratified by the State Board of Education.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-hs-no-statute' and v.is_current), 'researched', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Source opened and quote extracted by automated research. Human check pending.');
insert into rules (slug, rule_topic_id, scope_type, state_id, applies_to) values ('fl-college-nil-allowed', (select id from rule_topics where slug = 'nil-allowed'), 'state', (select id from states where code = 'FL'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, citation, effective_note, verification_status) values ((select id from rules where slug = 'fl-college-nil-allowed'), 1, 'yes', 'Yes. In a legislative finding, section 1006.74 says a college athlete "must have an equal opportunity to control and profit from the commercial use of her or his name, image, or likeness." The current section has four subsections (definition, workshops, liability, rulemaking) and none restricts athlete deals.', 'Section 1006.74, Florida Statutes (opening paragraph)', 'Created in 2020 (effective July 1, 2021) and revised by HB 7-B, effective February 16, 2023.', 'researched');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-college-nil-allowed' and v.is_current), (select id from sources where slug = 'fl-stat-1006-74'), 's. 1006.74, opening paragraph', 'participation in intercollegiate athletics should not infringe upon an intercollegiate athlete''s ability to earn compensation for her or his name, image, or likeness. An intercollegiate athlete must have an equal opportunity to control and profit from the commercial use of her or his name, image, or likeness, and be protected from unauthorized appropriation and commercial exploitation of her or his right to publicity, including her or his name, image, or likeness.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-college-nil-allowed' and v.is_current), 'researched', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Source opened and quote extracted by automated research. Human check pending.');
insert into rules (slug, rule_topic_id, scope_type, state_id, applies_to) values ('fl-college-education', (select id from rule_topics where slug = 'nil-education'), 'state', (select id from states where code = 'FL'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status) values ((select id from rules where slug = 'fl-college-education'), 1, 'yes', 'Yes. Every covered Florida college must run at least two financial literacy, life skills and entrepreneurship workshops, each at least five hours, in different semesters, before an athlete graduates.', 'Section 1006.74(2), Florida Statutes; Board of Governors Regulation 6.022(1)', 'researched');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-college-education' and v.is_current), (select id from sources where slug = 'fl-stat-1006-74'), 's. 1006.74(2)', 'A postsecondary educational institution must conduct at least two financial literacy, life skills, and entrepreneurship workshops, each for a minimum of 5 hours, before the graduation of an intercollegiate athlete. The workshops may not be identical, and the second workshop must include more rigorous instruction. The workshops may not be conducted in the same semester.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-college-education' and v.is_current), (select id from sources where slug = 'bog-reg-6-022'), 'Regulation 6.022(1)', 'Each university must conduct at least two financial literacy, life skills, and entrepreneurship workshops for a minimum of five (5) hours each consistent with the requirements in section 1006.74, Florida Statutes, prior to the graduation of the intercollegiate athlete.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-college-education' and v.is_current), 'researched', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Source opened and quote extracted by automated research. Human check pending.');
insert into rules (slug, rule_topic_id, scope_type, state_id, applies_to) values ('fl-college-agents', (select id from rule_topics where slug = 'agents'), 'state', (select id from states where code = 'FL'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status) values ((select id from rules where slug = 'fl-college-agents'), 1, 'yes_with_conditions', 'Yes, but the agent must hold a Florida athlete agent license to represent a college athlete on NIL contracts. A spouse, parent, sibling, grandparent or guardian is not treated as an athlete agent.', 'Sections 468.453(8) and 468.452(2), Florida Statutes', 'researched');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-college-agents' and v.is_current), (select id from sources where slug = 'fl-stat-468-453'), 's. 468.453(8)', 'Notwithstanding subsection (3), a person must hold a valid license as an athlete agent to act as an athlete agent representing an intercollegiate athlete for purposes of contracts that allow an intercollegiate athlete to profit from the commercial use of her or his name, image, or likeness', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-college-agents' and v.is_current), (select id from sources where slug = 'fl-stat-468-452'), 's. 468.452(2)', 'The term does not include a spouse, parent, sibling, grandparent, or guardian of the student athlete or an individual acting solely on behalf of a professional sports team or professional sports organization.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-college-agents' and v.is_current), 'researched', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Source opened and quote extracted by automated research. Human check pending.');
insert into rules (slug, rule_topic_id, scope_type, state_id, applies_to) values ('fl-college-disclosure', (select id from rule_topics where slug = 'disclosure-required'), 'state', (select id from states where code = 'FL'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status) values ((select id from rules where slug = 'fl-college-disclosure'), 1, 'not_addressed', 'Section 1006.74 contains no requirement to disclose NIL deals to the school. The reporting duty we found comes from NCAA rules. Florida''s athlete agent statutes (sections 468.454 and following) were not checked and may require notice of agent contracts.', 'Section 1006.74, Florida Statutes (no disclosure provision)', 'researched');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'fl-college-disclosure' and v.is_current), (select id from sources where slug = 'fl-stat-1006-74'), 's. 1006.74(1)-(4)', '(4) The Board of Governors and the State Board of Education shall adopt regulations and rules, respectively, to implement this section.History.—s. 1, ch. 2020-28; s. 20, ch. 2021-35; ss. 1, 2, ch. 2021-217; s. 2, ch. 2023-4.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
