insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status) values ((select id from rules where slug = 'ncaa-logos-marks'), 1, 'not_addressed', 'We found no rule in NCAA Bylaw Article 22 on athletes using school logos or marks in third-party deals. The NCAA tells athletes to "Review your campus NIL policy and applicable state law."', 'NCAA NIL page, "Getting started with NIL"', 'needs_verification');
