insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status) values ((select id from rules where slug = 'ncaa-recruiting'), 1, 'no', 'No. Pay to attend or compete for a specific school is pay-for-play and is not allowed.', 'NCAA NIL page, "What''s allowed vs. not allowed"', 'researched');
