insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status) values ((select id from rules where slug = 'ncaa-transfers'), 1, 'yes_with_conditions', 'Four-year transfers must report deals of $600 or more signed from the date they entered the Transfer Portal. A deal that was already cleared and stays in place does not need to be resubmitted.', 'NCAA Division I Bylaw 22.2.2.5.2', 'researched');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-transfers' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaw 22.2.2.5.2', 'Prospective four-year college transfers shall report all noninstitutional name, image, and likeness contracts or payment terms with compensation of $600 or more that have been executed from the date in which the student-athlete’s name was officially entered into the NCAA Transfer Portal. A transfer who has previously reported a deal that will remain in place upon transfer shall not be required to resubmit the deal if it has been cleared by the CSC.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-transfers' and v.is_current), 'researched', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Source opened and quote extracted by automated research. Human check pending.');
insert into rules (slug, rule_topic_id, scope_type, governing_body_id, applies_to) values ('ncaa-prospects-reporting', (select id from rule_topics where slug = 'prospects-reporting'), 'governing_body', (select id from governing_bodies where slug = 'ncaa'), 'both');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status) values ((select id from rules where slug = 'ncaa-prospects-reporting'), 1, 'yes', 'Yes. An athlete enrolling at a Division I school must report third-party deals of $600 or more made since the first day of junior year of high school (or July 1, 2025, if later). The deadline is 14 days after enrolling full time or before the team''s first game, whichever comes first.', 'NCAA Division I Bylaws 22.2.2.5.1 and 22.2.2.5.3', 'researched');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-prospects-reporting' and v.is_current), (select id from sources where slug = 'ncaa-d1-manual-2026-27'), 'Bylaws 22.2.2.5.1, 22.2.2.5.3', 'An incoming prospective student-athlete must report noninstitutional name, image and likeness contracts or payment terms not later than either 14 days after initial full-time enrollment at a Division I institution, or prior to the institution’s first scheduled contest against outside competition in the individual''s sport, whichever occurs first.', 'machine_raw_text', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'ncaa-prospects-reporting' and v.is_current), (select id from sources where slug = 'ncaa-nil-page'), 'High school prospects planning to play Division I', 'Report threshold: all third-party NIL deals worth $600 or more since July 1, 2025 or starting your junior year of high school, whichever is later', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
