insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status) values ((select id from rules where slug = 'csc-international'), 1, 'yes_with_conditions', 'International athletes must report deals of $600 or more like every Division I athlete, but whether a deal is legal for them can depend on immigration rules. The College Sports Commission tells them to consult their school before going ahead.', 'CSC FAQ, "Are international student-athletes required to report third-party NIL deals?"', 'researched');
