insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status) values ((select id from rules where slug = 'uf-nil-allowed'), 1, 'yes_with_conditions', 'Yes. UF tells its athletes they have full rights to profit from their NIL, and that every paid deal must be a real exchange: you provide a service or promotion and get paid for it.', 'UF, Overview of Gators NIL', 'researched');
