insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status) values ((select id from rules where slug = 'uf-prohibited-categories'), 1, 'no', 'UF does not allow NIL agreements with gambling or sports wagering vendors, or with vendors associated with performance enhancing drugs, both as defined by the NCAA. No other category limits were found in UF''s published material.', 'UF, Overview of Gators NIL', 'researched');
