insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status) values ((select id from rules where slug = 'uf-facilities'), 1, 'not_addressed', 'UF''s published NIL material does not say whether athletes can use UF facilities for sponsored shoots. Ask UAA Compliance before planning one.', 'UF, Overview of Gators NIL (no provision found)', 'needs_verification');
