insert into rules (slug, rule_topic_id, scope_type, institution_id, applies_to) values ('uf-international', (select id from rule_topics where slug = 'international-athletes'), 'institution', (select id from institutions where slug = 'university-of-florida'), 'college');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status) values ((select id from rules where slug = 'uf-international'), 1, 'only_with_approval', 'Talk to the UF International Center first. UF''s International Student Services says international athletes must not enter any NIL agreement without its guidance, that an athlete on an F-1 visa cannot perform services for a business while in the United States without proper authorization, and that NIL activity rarely qualifies for that authorization.', 'UF, Overview of Gators NIL; UF International Center NCAA FAQ', 'researched');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'uf-international' and v.is_current), (select id from sources where slug = 'uf-nil-overview'), 'International athletes', 'Prior to participating in any NIL opportunities, international athletes on F-1 visas are encouraged to contact the UF International Center prior to participation in NIL agreements.', 'machine_confirmed_twice', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'uf-international' and v.is_current), (select id from sources where slug = 'uf-iss-ncaa-faq'), 'NCAA FAQ', 'US student visa regulations may prevent NIL compensation for international students while in the US and there may also be tax implications. Therefore, international student-athletes must not enter into any NIL agreements without the guidance from the University of Florida International Students Services office', 'machine_confirmed_twice', '2026-10-03', 'Claude (automated source research)');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'uf-international' and v.is_current), (select id from sources where slug = 'uf-iss-ncaa-faq'), 'NCAA FAQ', 'the international student-athlete cannot engage in services for a business or company while in the US on an F-1 visa without proper authorization. ... Unfortunately, it is rare that an NIL activity will qualify for authorization.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
