insert into rules (slug, rule_topic_id, scope_type, district_id, applies_to) values ('scps-facilities', (select id from rule_topics where slug = 'school-facilities'), 'district', (select id from school_districts where slug = 'seminole-county-public-schools'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, conditions, citation, verification_status) values ((select id from rules where slug = 'scps-facilities'), 1, 'only_with_approval', 'Only through the district. Any outside use of a Seminole County Public Schools facility must be requested online through Facilitron, with payment and proof of insurance. District staff make the final decision.', 'The district''s Policy 7510 and Facility Use Handbook could not be opened, so whether they address commercial filming is not yet known.', 'SCPS Facility Requests and Rental page', 'needs_verification');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'scps-facilities' and v.is_current), (select id from sources where slug = 'scps-facility-use'), 'Facility Requests/Rental', 'Moving forward, the only way to request use of a district facility is by creating a Facilitron account and submitting a request online. ... Facilitron will also collect payment and proof of insurance (certificate of insurance) on Seminole County Public Schools'' behalf. ... Seminole County Public Schools'' administrative staff will make final decisions on all facility use requests.', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
insert into verification_events (entity_type, entity_id, status, method, verified_on, verified_by, notes) values ('rule_version', (select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'scps-facilities' and v.is_current), 'needs_verification', 'automated_fetch', '2026-10-03', 'Claude (automated source research)', 'Source opened and quote extracted by automated research. Human check pending.');
insert into rules (slug, rule_topic_id, scope_type, institution_id, applies_to) values ('shs-event-footage', (select id from rule_topics where slug = 'event-footage'), 'institution', (select id from institutions where slug = 'seminole-high-school-sanford'), 'high_school');
insert into rule_versions (rule_id, version_no, answer, summary, citation, verification_status) values ((select id from rules where slug = 'shs-event-footage'), 1, 'not_addressed', 'Seminole High School''s media credential page says credentialed coverage is "for news and editorial coverage" and that requests are due 48 hours before the event. We found no school rule on using event footage in an ad. Separately, FHSAA Bylaw 9.9.4.3 bars referring to a member school event or game in NIL activity.', 'Seminole High School Athletics, Media Credential Request', 'needs_verification');
insert into rule_version_sources (rule_version_id, source_id, locator, quote, quote_check, checked_on, checked_by) values ((select v.id from rule_versions v join rules r on r.id = v.rule_id where r.slug = 'shs-event-footage' and v.is_current), (select id from sources where slug = 'shs-media-credentials'), 'Media Credential Request', 'for news and editorial coverage ... DEADLINE 48 HOURS PRIOR TO EVENT START ... The dissemination of editorial content must be a primary purpose of the media outlet', 'machine_extracted', '2026-10-03', 'Claude (automated source research)');
