insert into school_nil_policies (institution_id, title, summary, policy_status, source_id, adopted_on, verification_status) values ((select id from institutions where slug = 'university-of-florida'), 'Overview of Gators NIL', 'UF publishes an athlete-facing NIL overview (dated August 6, 2025 in its URL) rather than a formal policy document. It covers what athletes can do, the NIL Go reporting rule, use of Gators marks and gear, prohibited vendors, international athletes and the support UF offers. UF''s older "Guidelines for Name, Image, and Likeness" page now reads "Updated information coming soon."', 'published', (select id from sources where slug = 'uf-nil-overview'), NULL, 'needs_verification');
insert into school_nil_policies (institution_id, title, summary, policy_status, source_id, verification_status) values ((select id from institutions where slug = 'seminole-high-school-sanford'), 'No school or district NIL policy found', 'We found no NIL policy, handbook language or form published by Seminole High School or Seminole County Public Schools. The district board policy manual and student conduct code could not be opened, so this is not yet confirmed. FHSAA Bylaw 9.9 applies to every member school. A school or district may add its own rules.', 'none_found', (select id from sources where slug = 'scps-policies'), 'needs_verification');
insert into nil_programs (institution_id, name, program_type, description, url, source_id, verification_status, sort_order) values ((select id from institutions where slug = 'university-of-florida'), 'Gators NIL Exchange', 'marketplace', 'UF says the exchange "allows fans, alumni, and local businesses to directly connect with Gator athletes to offer them opportunities."', 'https://floridagators.com/sports/2021/12/16/gators-made-name-image-likeness.aspx', (select id from sources where slug = 'uf-gators-made'), 'researched', 10);
insert into nil_programs (institution_id, name, program_type, description, url, source_id, verification_status, sort_order) values ((select id from institutions where slug = 'university-of-florida'), 'Florida Victorious', 'nil_entity', 'UF''s NIL page describes Florida Victorious as "an exclusive community for Gator Nation" that "strives to be the model NIL entity in collegiate athletics." Whether a payor counts as "associated" with a school is decided in NIL Go review.', 'https://floridavictorious.com/', (select id from sources where slug = 'uf-gators-made'), 'researched', 20);
insert into nil_programs (institution_id, name, program_type, description, url, source_id, verification_status, sort_order) values ((select id from institutions where slug = 'university-of-florida'), 'Gators Sports Properties', 'sponsorship_sales', 'The route for companies that want to sponsor or partner with the Florida Gators and their athletes.', 'https://floridagators.com/sports/2015/12/10/_sponsors_', (select id from sources where slug = 'uf-gators-made'), 'researched', 30);
insert into nil_programs (institution_id, name, program_type, description, url, source_id, verification_status, sort_order) values ((select id from institutions where slug = 'university-of-florida'), 'NIL Suite, Hawkins Center, Gators Experience and GatorMade', 'education', 'UF''s in-house support: one-on-one NIL advising, content help, and financial literacy, brand building and education workshops.', 'https://floridagators.com/sports/2025/8/6/overview-name-image-likeness', (select id from sources where slug = 'uf-gators-made'), 'researched', 40);
