insert into pages (path, page_type, state_id, institution_id, title, meta_description, h1, last_updated) values ('/nil/florida/high-schools/', 'high_school_directory', (select id from states where code = 'FL'), NULL, 'Florida High School NIL Rules by School | NIL Brand Academy', 'NIL rules, Form GA1 steps and school contacts for Florida high school athletes and parents, school by school.', 'Florida high schools', '2026-10-03');
insert into pages (path, page_type, state_id, institution_id, title, meta_description, h1, last_updated) values ('/nil/florida/colleges/university-of-florida/', 'college_hub', (select id from states where code = 'FL'), (select id from institutions where slug = 'university-of-florida'), 'University of Florida NIL Rules | NIL Brand Academy', 'What University of Florida athletes can and cannot do with NIL: NIL Go reporting, logo and gear rules, prohibited vendors, contacts and sources.', 'University of Florida NIL rules', '2026-10-03');
insert into pages (path, page_type, state_id, institution_id, title, meta_description, h1, last_updated) values ('/nil/florida/high-schools/seminole-high-school-sanford/', 'high_school_hub', (select id from states where code = 'FL'), (select id from institutions where slug = 'seminole-high-school-sanford'), 'Seminole High School (Sanford, FL) NIL Rules | NIL Brand Academy', 'NIL rules for Seminole High School athletes in Sanford, Florida: what FHSAA allows, Form GA1, school marks and facilities, parent guidance and sources.', 'Seminole High School NIL rules', '2026-10-03');
insert into pages (path, page_type, state_id, institution_id, title, meta_description, h1, last_updated) values ('/nil/sports/', 'sports_index', NULL, NULL, 'NIL by Sport | NIL Brand Academy', 'How NIL works sport by sport, with links to the schools that offer each sport.', 'NIL by sport', '2026-10-03');
